let selected = '{SelectedTables}';
let tables = split(selected, '|');
let sub = '{Subscription}';
let rg = '{resourceGroup}';
let ws = '{WorkspaceName}';
let ret = '{ArchiveRetentionDays}';
let total = '{ArchiveTotalRetentionDays}';
range i from 0 to (array_length(tables) - 1) step 1
| extend t = tostring(tables[i])
| where isnotempty(t)
| order by i asc
| serialize
| extend rn = row_number() - 1
| where rn >= 0 and rn < 20
| extend req = strcat('{"httpMethod":"PATCH","name":"req', tostring(rn), '","url":"', sub, '/resourcegroups/', rg, '/providers/Microsoft.OperationalInsights/workspaces/', ws, '/tables/', t, '?api-version=2023-09-01","content":{"properties":{"retentionInDays":', ret, ',"totalRetentionInDays":', total, '}}}')
| summarize reqs = make_list(req)
| project body = strcat('{"requests":[', strcat_array(reqs, ','), ']}')

